const maxImportRows = 10000

// importCustomers creates the customers in a CSV body (see readCustomerCSV): all of them, or none when a row is refused.
// With ?dry_run=true the rows are only checked.
func (s *Server) importCustomers(w http.ResponseWriter, r *http.Request, p auth.Principal) {
	rows, status, code := readCustomerCSV(r.Body)
	if status != 0 {
		writeError(w, status, code, importMessages[code])
		return
	}
	created, refused, err := s.store.ImportCustomers(p.OrgID, rows, s.clock.Now(), r.URL.Query().Get("dry_run") == "true")
	if err != nil {
		s.storeError(w, err)
		return
	}
	if len(refused) > 0 {
		writeJSON(w, http.StatusUnprocessableEntity, map[string]any{"error": "invalid_rows", "rows": refused})
		return
	}
	if r.URL.Query().Get("dry_run") == "true" {
		writeJSON(w, http.StatusOK, map[string]int{"created": 0, "would_create": len(rows)})
		return
	}
	for _, c := range created {
		s.publish(r.Context(), p.OrgID, "customer.created", c)
	}
	writeJSON(w, http.StatusCreated, map[string]any{"created": len(created), "items": created})
