var importMessages = map[string]string{
	"invalid_header": `the first record must be a header with "name" and "email" columns`,
	"invalid_csv":    "the body is not valid CSV",
	"too_many_rows":  "an import may have at most 10000 records",
}

// readCustomerCSV reads a customer import: a header record with "name" and "email" columns, optionally
// "default_payment_method" and "metadata.<key>" columns, then the data records. Header names match ignoring case and
// surrounding spaces; other columns are ignored. A byte order mark and blank lines are skipped. It returns the rows, or
// the status and error code of the problem (status 0 when there is none).
func readCustomerCSV(body io.Reader) (rows []store.CustomerImportRow, status int, code string) {
	br := bufio.NewReader(body)
	if b, _ := br.Peek(3); bytes.Equal(b, []byte("\xEF\xBB\xBF")) {
		_, _ = br.Discard(3)
	}
	cr := csv.NewReader(br)
	cr.FieldsPerRecord = -1 // short records read as empty cells; the rows are checked later
	head, err := cr.Read()
	if errors.Is(err, io.EOF) {
		return nil, http.StatusUnprocessableEntity, "invalid_header"
	}
	if err != nil {
		return nil, http.StatusBadRequest, "invalid_csv"
	}
	cols := map[string]int{} // the first column of each known name
	type metaCol struct {
		col int
		key string
	}
	var metaCols []metaCol
	for i, h := range head {
		name := strings.TrimSpace(h)
		if len(name) > len("metadata.") && strings.EqualFold(name[:len("metadata.")], "metadata.") {
			if key := strings.TrimSpace(name[len("metadata."):]); key != "" {
				metaCols = append(metaCols, metaCol{i, key})
			}
			continue
		}
		if _, ok := cols[strings.ToLower(name)]; !ok {
			cols[strings.ToLower(name)] = i
		}
	}
	if _, ok := cols["name"]; !ok {
		return nil, http.StatusUnprocessableEntity, "invalid_header"
	}
	if _, ok := cols["email"]; !ok {
		return nil, http.StatusUnprocessableEntity, "invalid_header"
	}
	cell := func(rec []string, name string) string {
		i, ok := cols[name]
		if !ok || i >= len(rec) {
			return ""
		}
		return strings.TrimSpace(rec[i])
	}
	for {
		rec, err := cr.Read()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, http.StatusBadRequest, "invalid_csv"
		}
		if len(rows) == maxImportRows {
			return nil, http.StatusRequestEntityTooLarge, "too_many_rows"
		}
		line, _ := cr.FieldPos(0)
		row := store.CustomerImportRow{Line: line, Name: cell(rec, "name"), Email: cell(rec, "email"),
			DefaultPaymentMethod: cell(rec, "default_payment_method")}
		for _, m := range metaCols {
			if v := strings.TrimSpace(rec[m.col]); v != "" && m.col < len(rec) {
				if row.Metadata == nil {
					row.Metadata = map[string]string{}
				}
				row.Metadata[m.key] = v
			}
		}
		rows = append(rows, row)
	}
	return rows, 0, ""
}

