package api_test

import (
	"fmt"
	"net/http"
	"slices"
	"strings"
	"testing"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/store"
)

// importedCustomers counts the customers of an organization, and its customer.created events.
func importedCustomers(t *testing.T, e *apitest.Env, org apitest.Org) (customers, events int) {
	t.Helper()
	var cs struct{ Items []store.Customer }
	e.MustDo(http.StatusOK, "GET", "/v1/customers?limit=100", org.Key, nil, &cs)
	var evs struct{ Items []store.Event }
	e.MustDo(http.StatusOK, "GET", "/v1/events?type=customer.created", org.Key, nil, &evs)
	return len(cs.Items), len(evs.Items)
}

func TestImportCustomers(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Existing", "taken@example.com")
	customers, events := importedCustomers(t, e, e.Acme)

	// A byte order mark, spaces and case in the header, columns in any order, an ignored column, quoted fields with commas,
	// quotes and a line break, CRLF and LF line ends, blank lines and empty metadata cells.
	body := "\xEF\xBB\xBF Name ,EMAIL,Notes,default_payment_method,metadata.CRM ,metadata.plan\r\n" +
		"\"Doe, Jane \"\"JD\"\"\",jane@example.com,x,pm_card_1,7,pro\r\n" +
		"\r\n" +
		"\"Ann\nLee\", Ann@Example.com ,,,,\n" +
		"\n" +
		"Bob,bob@example.com,,,,\n"
	var out struct {
		Created int                `json:"created"`
		Items   []store.Customer   `json:"items"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, body, &out)
	if out.Created != 3 || len(out.Items) != 3 {
		t.Fatalf("created = %+v", out)
	}
	jane, ann, bob := out.Items[0], out.Items[1], out.Items[2]
	if jane.Name != `Doe, Jane "JD"` || jane.Email != "jane@example.com" || jane.DefaultPaymentMethod != "pm_card_1" ||
		jane.Metadata["CRM"] != "7" || jane.Metadata["plan"] != "pro" || len(jane.Metadata) != 2 {
		t.Fatalf("jane = %+v", jane)
	}
	if ann.Name != "Ann\nLee" || ann.Email != "Ann@Example.com" || ann.Metadata != nil {
		t.Fatalf("ann = %+v", ann)
	}
	if bob.Name != "Bob" || bob.Metadata != nil || bob.DefaultPaymentMethod != "" {
		t.Fatalf("bob = %+v", bob)
	}
	if got := e.MustDo(http.StatusOK, "GET", "/v1/customers/"+ann.ID, e.Acme.Key, nil, nil); !strings.Contains(string(got.Body), "Ann\\nLee") {
		t.Fatalf("ann is not stored: %s", got)
	}
	if c, ev := importedCustomers(t, e, e.Acme); c != customers+3 || ev != events+3 {
		t.Fatalf("after import: %d customers, %d events; want %d and %d", c, ev, customers+3, events+3)
	}
}

func TestImportCustomersHeaderOnly(t *testing.T) {
	e := apitest.New(t)
	var out struct {
		Created int               `json:"created"`
		Items   []store.Customer `json:"items"`
	}
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, "name,email\n", &out)
	if out.Created != 0 || out.Items == nil {
		t.Fatalf("header only = %+v", out)
	}
	r := e.Do("POST", "/v1/customers/import?dry_run=true", e.Acme.Key, "name,email\n")
	if r.Code != http.StatusOK || r.Map(t)["would_create"] != float64(0) {
		t.Fatalf("header only, dry run: %s", r)
	}
}

func TestImportCustomersDryRun(t *testing.T) {
	e := apitest.New(t)
	customers, events := importedCustomers(t, e, e.Acme)
	body := "name,email\nJane,jane@example.com\nJohn,john@example.com\n"
	r := e.MustDo(http.StatusOK, "POST", "/v1/customers/import?dry_run=true", e.Acme.Key, body, nil)
	if got := r.Map(t); got["created"] != float64(0) || got["would_create"] != float64(2) {
		t.Fatalf("dry run = %v", got)
	}
	if c, ev := importedCustomers(t, e, e.Acme); c != customers || ev != events {
		t.Fatalf("dry run created %d customers and %d events", c-customers, ev-events)
	}
	if r := e.Do("POST", "/v1/customers/import?dry_run=true", e.Acme.Key, "name,email\nJane,bad\n"); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_rows" {
		t.Fatalf("dry run with a bad row: %s", r)
	}
}

func TestImportCustomersInvalidHeader(t *testing.T) {
	e := apitest.New(t)
	for _, body := range []string{"", "\r\n\r\n", "Name,Mail\nJane,jane@example.com\n", "email,Nickname\njane@example.com,x\n"} {
		if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, body); r.Code != http.StatusUnprocessableEntity || r.Map(t)["error"] != "invalid_header" {
			t.Fatalf("%q: %s", body, r)
		}
	}
}

func TestImportCustomersInvalidCSV(t *testing.T) {
	e := apitest.New(t)
	for _, body := range []string{
		"name,email\nJane,\"jane@example.com\n",   // unterminated quote
		"name,email\nJa\"ne,jane@example.com\n",   // quote inside an unquoted field
		"name,email\n\"Jane\"x,jane@example.com\n", // text after a closing quote
	} {
		if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, body); r.Code != http.StatusBadRequest || r.Map(t)["error"] != "invalid_csv" {
			t.Fatalf("%q: %s", body, r)
		}
	}
}

func TestImportCustomersTooManyRows(t *testing.T) {
	e := apitest.New(t)
	var ok, tooMany strings.Builder
	ok.WriteString("name,email\n")
	tooMany.WriteString("name,email\n")
	for i := 0; i <= 10000; i++ {
		fmt.Fprintf(&tooMany, "Person %d,p%d@example.com\n", i, i)
		if i < 10000 {
			fmt.Fprintf(&ok, "Person %d,p%d@example.com\n", i, i)
		}
	}
	if r := e.Do("POST", "/v1/customers/import?dry_run=true", e.Acme.Key, ok.String()); r.Code != http.StatusOK || r.Map(t)["would_create"] != float64(10000) {
		t.Fatalf("10,000 rows: %s", r)
	}
	if r := e.Do("POST", "/v1/customers/import", e.Acme.Key, tooMany.String()); r.Code != http.StatusRequestEntityTooLarge || r.Map(t)["error"] != "too_many_rows" {
		t.Fatalf("10,001 rows: %s", r)
	}
	if c, _ := importedCustomers(t, e, e.Acme); c != 0 {
		t.Fatalf("a refused import created %d customers", c)
	}
}

func TestImportCustomersInvalidRows(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Acme, "Existing", "taken@example.com")
	customers, events := importedCustomers(t, e, e.Acme)

	// Line numbers: the header is line 1, and a record that spans lines starts where it begins.
	body := "name,email,default_payment_method\n" + // 1
		"Ann,ann@example.com,pm_1\n" + // 2: fine
		",nobody@example.com,\n" + // 3: missing_name
		"\"Multi\nLine\",bad-email,\n" + // 4-5: invalid_email
		"Cy,cy@example.com,card_123\n" + // 6: invalid_payment_method
		"Dee,TAKEN@example.com,\n" + // 7: email_taken
		"Eve,ann@EXAMPLE.com,\n" + // 8: duplicate_email (of line 2)
		"Fay,fay@example.com,\n" + // 9: fine
		"Gus,,\n" + // 10: invalid_email
		"Hal,fay@example.com,\n" + // 11: duplicate_email (of line 9)
		",,\n" + // 12: missing_name, before invalid_email
		"Solo\n" // 13: short record, no email
	want := []store.RowError{
		{Row: 3, Code: "missing_name"},
		{Row: 4, Code: "invalid_email"},
		{Row: 6, Code: "invalid_payment_method"},
		{Row: 7, Code: "email_taken"},
		{Row: 8, Code: "duplicate_email"},
		{Row: 10, Code: "invalid_email"},
		{Row: 11, Code: "duplicate_email"},
		{Row: 12, Code: "missing_name"},
		{Row: 13, Code: "invalid_email"},
	}
	for _, path := range []string{"/v1/customers/import", "/v1/customers/import?dry_run=true"} {
		r := e.Do("POST", path, e.Acme.Key, body)
		var out struct {
			Error string           `json:"error"`
			Rows  []store.RowError `json:"rows"`
		}
		r.JSON(t, &out)
		if r.Code != http.StatusUnprocessableEntity || out.Error != "invalid_rows" || !slices.Equal(out.Rows, want) {
			t.Fatalf("%s: %s", path, r)
		}
	}
	if c, ev := importedCustomers(t, e, e.Acme); c != customers || ev != events {
		t.Fatalf("a refused import created %d customers and %d events", c-customers, ev-events)
	}
}

func TestImportCustomersEmailIsScopedToOrganization(t *testing.T) {
	e := apitest.New(t)
	e.CreateCustomer(e.Globex, "Elsewhere", "shared@example.com")
	e.MustDo(http.StatusCreated, "POST", "/v1/customers/import", e.Acme.Key, "name,email\nShared,shared@example.com\n", nil)
}

